//! The generated OpenAPI 3.0 document.
//!
//! GENERATED FROM THE DTO TYPES, CHECKED IN, DRIFT-TESTED. The component
//! schemas come from `schemars` over `crate::contract` and `crate::problem`;
//! the path table below names every route `crate::app::router` serves. The
//! checked-in copy is `schemas/logweir-api-v1.openapi.json`, regenerated by
//! `just schema` and compared by `just schema-check` and by
//! `tests/contract.rs::the_checked_in_openapi_document_is_what_the_types_generate`.
//! Every route's possible problem codes are listed under
//! `x-logweir-problem-codes`, and a test asserts each code in
//! [`crate::problem::ProblemCode::ALL`] appears somewhere.

use schemars::gen::SchemaSettings;
use serde_json::{json, Map, Value};

use crate::contract as c;
use crate::problem::{Problem, ProblemCode};

/// The document version. `/api/v1` is not yet a stability promise.
pub const DOCUMENT_VERSION: &str = "1.0.0-alpha.1";

fn schema_ref(name: &str) -> Value {
    json!({ "$ref": format!("#/components/schemas/{name}") })
}

fn codes(list: &[ProblemCode]) -> Value {
    Value::Array(
        list.iter()
            .map(|c| Value::String(c.as_str().to_string()))
            .collect(),
    )
}

/// Problem codes any `/api/v1` route can return.
const COMMON: &[ProblemCode] = &[
    ProblemCode::HeaderNotAllowed,
    ProblemCode::MisdirectedRequest,
    ProblemCode::MethodNotAllowed,
    ProblemCode::InternalError,
    ProblemCode::Unauthenticated,
    ProblemCode::SessionExpired,
];

const NAMESPACED: &[ProblemCode] = &[ProblemCode::NamespaceForbidden, ProblemCode::Forbidden];

const KUBE: &[ProblemCode] = &[
    ProblemCode::RateLimited,
    ProblemCode::KubernetesUnavailable,
    ProblemCode::UpstreamTimeout,
];

const LIST: &[ProblemCode] = &[
    ProblemCode::MalformedRequest,
    ProblemCode::ValidationFailed,
    ProblemCode::CursorInvalid,
    ProblemCode::CursorExpired,
];

const GET: &[ProblemCode] = &[ProblemCode::MalformedRequest, ProblemCode::NotFound];

const UNSAFE: &[ProblemCode] = &[
    ProblemCode::OriginMismatch,
    ProblemCode::UnsupportedMediaType,
    ProblemCode::PayloadTooLarge,
    ProblemCode::MalformedRequest,
    ProblemCode::ValidationFailed,
];

const CREATE: &[ProblemCode] = &[
    ProblemCode::IdempotencyKeyRequired,
    ProblemCode::IdempotencyKeyInvalid,
    ProblemCode::IdempotencyConflict,
    ProblemCode::StateConflict,
];

const COMMAND: &[ProblemCode] = &[
    ProblemCode::IdempotencyKeyInvalid,
    ProblemCode::PreconditionFailed,
    ProblemCode::NotFound,
];

/// Problem codes reserved for later stages, with no producing route yet.
const RESERVED: &[ProblemCode] = &[ProblemCode::ApprovalRequired, ProblemCode::PolicyMismatch];

fn all_codes(groups: &[&[ProblemCode]]) -> Vec<ProblemCode> {
    let mut out: Vec<ProblemCode> = Vec::new();
    for group in groups {
        for code in *group {
            if !out.contains(code) {
                out.push(*code);
            }
        }
    }
    out.sort_by_key(|c| c.as_str());
    out
}

struct Op<'a> {
    method: &'static str,
    operation_id: &'a str,
    summary: &'a str,
    parameters: Vec<Value>,
    request: Option<&'a str>,
    success: Vec<(&'a str, &'a str, &'a str)>,
    problems: Vec<ProblemCode>,
}

fn param(name: &str, location: &str, description: &str, schema: Value, required: bool) -> Value {
    json!({
        "name": name,
        "in": location,
        "required": required,
        "description": description,
        "schema": schema,
    })
}

fn ns() -> Value {
    param(
        "ns",
        "path",
        "An explicitly granted namespace. An ungranted namespace is namespace_forbidden whether or not it exists.",
        json!({ "type": "string" }),
        true,
    )
}

fn name() -> Value {
    param(
        "name",
        "path",
        "The object name.",
        json!({ "type": "string" }),
        true,
    )
}

fn list_params() -> Vec<Value> {
    vec![
        ns(),
        param(
            "limit",
            "query",
            "Page size, 1 to 200. Default 50.",
            json!({ "type": "integer", "minimum": 1, "maximum": 200, "default": 50 }),
            false,
        ),
        param(
            "cursor",
            "query",
            "The opaque nextCursor of the previous page. Bound to actor, route, namespace and filters; expires after 15 minutes.",
            json!({ "type": "string" }),
            false,
        ),
        param(
            "labelSelector",
            "query",
            "Equality-only label selector, key=value terms separated by commas.",
            json!({ "type": "string" }),
            false,
        ),
    ]
}

fn idempotency_key() -> Value {
    param(
        "Idempotency-Key",
        "header",
        "8 to 128 visible ASCII characters. The object name is derived from (actor, namespace, route, key); a replay of the same request returns 200 with the same object, a different request with the same key is idempotency_conflict.",
        json!({ "type": "string", "minLength": 8, "maxLength": 128 }),
        true,
    )
}

fn origin() -> Value {
    param(
        "Origin",
        "header",
        "Must equal the configured public origin exactly.",
        json!({ "type": "string" }),
        true,
    )
}

fn operation(op: &Op<'_>) -> Value {
    let mut responses = Map::new();
    for (status, description, schema) in &op.success {
        // An empty schema name means a response with NO body: a 204, or a 303
        // whose only payload is `Location` and `Set-Cookie`. Emitting
        // `$ref: #/components/schemas/` for those would be an invalid document.
        let response = if schema.is_empty() {
            json!({ "description": description })
        } else {
            json!({
                "description": description,
                "content": { "application/json": { "schema": schema_ref(schema) } }
            })
        };
        responses.insert((*status).to_string(), response);
    }
    responses.insert(
        "default".to_string(),
        json!({
            "description": "An application/problem+json error; the possible codes are listed in x-logweir-problem-codes.",
            "content": { "application/problem+json": { "schema": schema_ref("Problem") } }
        }),
    );
    let mut out = Map::new();
    out.insert("operationId".into(), json!(op.operation_id));
    out.insert("summary".into(), json!(op.summary));
    if !op.parameters.is_empty() {
        out.insert("parameters".into(), Value::Array(op.parameters.clone()));
    }
    if let Some(request) = op.request {
        out.insert(
            "requestBody".into(),
            json!({
                "required": true,
                "content": { "application/json": { "schema": schema_ref(request) } }
            }),
        );
    }
    out.insert("responses".into(), Value::Object(responses));
    out.insert("x-logweir-problem-codes".into(), codes(&op.problems));
    Value::Object(out)
}

