/// The pretty-printed document, newline-terminated.
#[must_use]
pub fn openapi_document() -> String {
    let settings = SchemaSettings::openapi3();
    let mut generator = settings.into_generator();
    // Registering a type adds it and everything it names to the definitions.
    let _ = generator.subschema_for::<Problem>();
    let _ = generator.subschema_for::<c::HealthStatus>();
    let _ = generator.subschema_for::<c::SessionResponse>();
    let _ = generator.subschema_for::<c::NamespaceListResponse>();
    let _ = generator.subschema_for::<c::CreateConnectionRequest>();
    let _ = generator.subschema_for::<c::ConnectionList>();
    let _ = generator.subschema_for::<c::ConnectionResponse>();
    let _ = generator.subschema_for::<c::CreateScheduleRequest>();
    let _ = generator.subschema_for::<c::SetSuspensionRequest>();
    let _ = generator.subschema_for::<c::ScheduleList>();
    let _ = generator.subschema_for::<c::ScheduleResponse>();
    let _ = generator.subschema_for::<c::BackupList>();
    let _ = generator.subschema_for::<c::BackupResponse>();
    let _ = generator.subschema_for::<c::CreateRestoreRequest>();
    let _ = generator.subschema_for::<c::RestoreList>();
    let _ = generator.subschema_for::<c::RestoreResponse>();
    let _ = generator.subschema_for::<c::ApprovalList>();
    let _ = generator.subschema_for::<c::ApprovalResponse>();
    let _ = generator.subschema_for::<c::ApprovalPacketResponse>();
    let _ = generator.subschema_for::<c::OperationResponse>();
    let definitions = generator.take_definitions();
    let schemas: Map<String, Value> = definitions
        .into_iter()
        .map(|(k, v)| (k, serde_json::to_value(v).expect("a schema serialises")))
        .collect();

    let document = json!({
        "openapi": "3.0.3",
        "info": {
            "title": "Logweir product API",
            "version": DOCUMENT_VERSION,
            "description": "The bounded shared-console product API (PLAT-17.1). Not a Kubernetes proxy: no generic resource path, no Secret, Pod, log, exec or Job access, no delete, and no arbitrary patch. Every error is application/problem+json. Unsafe methods require Content-Type: application/json and an Origin equal to the configured public origin. Durable creates require Idempotency-Key. Capabilities without a route are advertised false in /api/v1/session.",
        },
        "paths": paths(),
        "components": {
            "schemas": Value::Object(schemas),
        },
        "x-logweir-reserved-problem-codes": codes(RESERVED),
    });
    let mut text = serde_json::to_string_pretty(&document).expect("the document serialises");
    text.push('\n');
    text
}
